CREATE TABLE IF NOT EXISTS users (id INT NOT NULL AUTO_INCREMENT, name VARCHAR(100) NOT NULL, user_id VARCHAR(50) DEFAULT NULL, email VARCHAR(150) NOT NULL, password VARCHAR(255) NOT NULL, created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP, role VARCHAR(20) NOT NULL DEFAULT 'user', PRIMARY KEY (id), UNIQUE KEY email (email), UNIQUE KEY user_id (user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS cakes (id INT NOT NULL AUTO_INCREMENT, name VARCHAR(150) NOT NULL, category VARCHAR(100) DEFAULT NULL, price DECIMAL(10,2) NOT NULL, price_250g DECIMAL(10,2) DEFAULT NULL, price_1kg DECIMAL(10,2) DEFAULT NULL, description TEXT, image VARCHAR(255) DEFAULT NULL, created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS orders (id INT NOT NULL AUTO_INCREMENT, user_id INT DEFAULT NULL, full_name VARCHAR(100) NOT NULL, mobile VARCHAR(15) NOT NULL, delivery_address TEXT NOT NULL, pincode VARCHAR(10) NOT NULL, total_amount DECIMAL(10,2) NOT NULL, status VARCHAR(50) DEFAULT 'Pending', created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), KEY user_id (user_id), CONSTRAINT orders_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS order_items (id INT NOT NULL AUTO_INCREMENT, order_id INT NOT NULL, cake_name VARCHAR(100) NOT NULL, weight VARCHAR(20) DEFAULT NULL, price DECIMAL(10,2) NOT NULL, quantity INT NOT NULL, PRIMARY KEY (id), KEY fk_order (order_id), CONSTRAINT order_items_order_fk FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
